#!/usr/bin/env python3
"""Rename photos to YYYY-MM-DD[-N].ext using the date found in their name."""
import argparse
import datetime
import re
import sys
from pathlib import Path

DATE = re.compile(r"(?<!\d)((?:19|20)\d{2})[-_ ]?(\d{2})[-_ ]?(\d{2})(?!\d)")
DONE = re.compile(r"^\d{4}-\d{2}-\d{2}(-\d+)?\.[a-z0-9]+$")


def find_date(name):
    for m in DATE.finditer(name):
        try:
            return datetime.date(int(m[1]), int(m[2]), int(m[3]))
        except ValueError:
            continue
    return None


def plan(folder):
    names = sorted(p.name for p in folder.iterdir() if p.is_file())
    taken = set(names)
    moves = []
    for name in names:
        if DONE.match(name):
            continue
        day = find_date(name)
        if day is None:
            continue
        ext = Path(name).suffix.lower()
        n, new = 1, day.isoformat() + ext
        while new in taken:
            n += 1
            new = f"{day.isoformat()}-{n}{ext}"
        taken.add(new)
        moves.append((name, new))
    return moves


def main(argv=None):
    ap = argparse.ArgumentParser(description=__doc__)
    ap.add_argument("folder")
    ap.add_argument("--dry-run", action="store_true")
    args = ap.parse_args(argv)
    folder = Path(args.folder)
    if not folder.is_dir():
        print(f"not a folder: {folder}", file=sys.stderr)
        return 2
    for old, new in plan(folder):
        print(f"{old} -> {new}")
        if not args.dry_run:
            (folder / old).rename(folder / new)
    return 0


if __name__ == "__main__":
    sys.exit(main())
